def step(title, text, code=None, example=None):
    value = {"title": title, "text": text}
    if code is not None: value["code"] = code
    if example is not None: value["example"] = example
    return value


def tutorial(key, goal, prerequisites, steps, worked_steps, worked_code, pitfalls, interview):
    return {"goal": goal, "prerequisites": [PREREQUISITES[name] for name in prerequisites],
            "steps": steps,
            "workedExample": {"title": "Похожий случай, разобранный до самостоятельной задачи", "steps": worked_steps, "code": worked_code},
            "taskBridge": EXERCISES[key]["description"],
            "pitfalls": [{"symptom": a, "explanation": b} for a, b in pitfalls],
            "interview": interview}


